@js:
let r = java.hexDecodeToString(result).split("#");
let key = r[0]
let page = r[1]
let list = [];
if (key.includes("@")) {
    let url = `${source.bookSourceUrl}search?wd=${key}&page=${page}`;
    let res = java.ajax(url);
    list = JSON.parse(res).data?.books;
} else {
    let p = ["番茄", "七猫", "猫眼", "得间", "书旗", "滴滴"];
    let urls = p.map(x => `${source.bookSourceUrl}search?wd=${key}@${x}&page=1`);
    let res = java.ajaxAll(urls).map(x => JSON.parse(x.body()).data?.books);

    for (let i = 0; i < 9; i++) {
        for (let j = 0; j < res.length; j++) {
            if (res[j] && res[j][i]) {
                list.push(res[j][i]);
            }
        }
    }
}
list.map(x=>JSON.stringify(x));

